<script setup lang="ts">
import { Plus, Printer, Download, Search, LockKeyhole, Unlock, CalendarDays, ChevronDown, ShieldCheck } from '@lucide/vue'
import type { Doctor } from '../domain/types'
import { monthLabel } from '../domain/calendar'
import { clockLabel, planShifts, shiftStyle } from '../domain/shifts'
import { downloadText, rosterCsv } from '../services/exports'
const w = useWorkspace(), view = ref<'code' | 'time' | 'both'>('code'), search = ref(''), unit = ref('all'), newMonth = ref(false), expanded = ref(false), lockConfirm = ref(false)
const selected = ref<{ doctor: Doctor; date: string } | null>(null)
const doctors = computed(() => w.summaries.value.map(r => r.doctor).filter(d => d.name.toLowerCase().includes(search.value.toLowerCase()) && (unit.value === 'all' || d.unit === unit.value)))
const legend = computed(() => w.data.value && w.plan.value ? planShifts(w.data.value, w.plan.value).filter(s => s.active || Object.values(w.plan.value!.assignments).some(row => Object.values(row).includes(s.code))) : [])
const shownIssues = computed(() => w.issues.value.filter(i => !i.doctorId || doctors.value.some(d => d.id === i.doctorId)))
function exportCsv() { if (w.data.value && w.plan.value) downloadText(rosterCsv(w.data.value, w.plan.value), `Jadwal_${w.activeMonth.value}.csv`, 'text/csv;charset=utf-8') }
async function toggleLock() { const ok = await w.mutate(data => { data.plans[w.activeMonth.value]!.locked = !data.plans[w.activeMonth.value]!.locked; return data }, `${w.plan.value?.locked ? 'Membuka' : 'Mengunci'} jadwal ${w.activeMonth.value}`, true); if (ok) lockConfirm.value = false }
</script>
<template>
  <PageHeading title="Jadwal bulanan" subtitle="Klik isian untuk mengubah dinas. Jam kerja dan pemeriksaan diperbarui otomatis." eyebrow="Kelola dinas"><MonthSelect/><button class="btn btn-secondary" :disabled="!w.canEdit.value" @click="newMonth = true"><Plus :size="16"/>Bulan baru</button></PageHeading>
  <template v-if="w.plan.value">
    <div class="panel overflow-hidden"><div class="flex flex-col justify-between gap-4 border-b border-slate-100 px-5 py-5 xl:flex-row xl:items-center"><div class="flex flex-wrap items-center gap-3"><h2 class="text-sm font-semibold">{{ monthLabel(w.activeMonth.value) }}</h2><span class="tag" :class="w.plan.value.locked ? 'bg-slate-100 text-slate-500' : 'bg-brand-50 text-brand-700'"><component :is="w.plan.value.locked ? LockKeyhole : ShieldCheck" :size="12"/>{{ w.plan.value.locked ? 'Terkunci' : 'Draf jadwal' }}</span></div><div class="flex flex-wrap gap-2"><button class="btn btn-secondary py-2 text-xs" @click="exportCsv"><Download :size="14"/>Ekspor CSV</button><NuxtLink to="/cetak" class="btn btn-secondary py-2 text-xs"><Printer :size="14"/>Cetak / PDF</NuxtLink><button v-if="w.isAdmin.value" class="btn btn-secondary py-2 text-xs" :disabled="w.saving.value" @click="lockConfirm = true"><component :is="w.plan.value.locked ? Unlock : LockKeyhole" :size="14"/>{{ w.plan.value.locked ? 'Buka kunci' : 'Kunci bulan' }}</button></div></div>
      <div class="flex flex-col justify-between gap-3 px-5 py-4 lg:flex-row"><div class="flex gap-2"><label class="relative max-w-60"><Search class="absolute top-3 left-3 text-slate-400" :size="15"/><input v-model="search" class="field py-2.5 pl-9" placeholder="Cari dokter" aria-label="Cari dokter"/></label><select v-model="unit" class="field w-auto" aria-label="Filter layanan"><option value="all">Semua dokter</option><option value="rotasi">Rotasi layanan</option><option value="anak">Ruang anak</option></select></div><div class="flex w-fit items-center rounded-xl bg-slate-100 p-1"><button v-for="v in [{ key: 'code', label: 'Kode' }, { key: 'time', label: 'Jam' }, { key: 'both', label: 'Kode & jam' }]" :key="v.key" class="rounded-lg px-3 py-2 text-xs font-medium" :class="view === v.key ? 'bg-white text-brand-700 shadow-sm' : 'text-slate-400'" :aria-pressed="view === v.key" @click="view = v.key as typeof view">{{ v.label }}</button></div></div>
      <RosterGrid :doctors="doctors" :view="view" @select="(doctor, date) => selected = { doctor, date }"/>
      <div class="flex flex-wrap items-center justify-between gap-2 bg-slate-50/60 px-5 py-3 text-[11px] text-slate-400"><p>{{ w.plan.value.frozenThrough ? `Tanggal 1–${w.plan.value.frozenThrough} dikunci sebagai riwayat.` : 'Sel kode dinas dapat diubah sesuai hak akun.' }} <NuxtLink v-if="w.isAdmin.value" to="/pengaturan" class="text-brand-700">Atur periode</NuxtLink></p><p class="flex items-center gap-1.5"><span class="h-1.5 w-1.5 rounded-full bg-rose-500"/>Titik merah: perlu diperiksa</p></div>
    </div>
    <div class="panel mt-5 p-5"><div class="mb-4 flex items-center justify-between"><h2 class="text-xs font-semibold">Keterangan kode & jam</h2><p class="text-[10px] text-slate-400">+1 = selesai besok</p></div><div class="flex flex-wrap gap-x-5 gap-y-3"><div v-for="s in legend" :key="s.code" class="flex items-center gap-2"><span class="tag px-2 py-1 text-[10px] font-semibold" :class="shiftStyle(s)">{{ s.code }}</span><span class="text-[10px] text-slate-500">{{ clockLabel(s) }}</span></div></div></div>
    <section class="panel mt-5 p-5"><button class="flex w-full items-center justify-between text-left" :aria-expanded="expanded" @click="expanded = !expanded"><div><h2 class="text-sm font-semibold">Pemeriksaan pola & cakupan layanan</h2><p class="mt-1 text-xs text-slate-400">{{ shownIssues.length }} catatan · termasuk riwayat dan data batas bulan</p></div><ChevronDown :size="18" class="text-slate-400 transition-transform" :class="expanded ? 'rotate-180' : ''"/></button><div v-if="expanded" class="mt-5 border-t border-slate-100 pt-5"><IssueList :issues="shownIssues" :limit="60"/></div></section>
  </template>
  <div v-else class="panel p-10 text-center"><CalendarDays :size="30" class="mx-auto mb-4 text-brand-600"/><p class="text-sm text-slate-500">Belum ada jadwal untuk bulan ini.</p><button v-if="w.canEdit.value" class="btn btn-primary mt-5" @click="newMonth = true">Buat jadwal</button></div>
  <AssignmentModal v-if="selected" :doctor="selected.doctor" :date="selected.date" @close="selected = null"/>
  <NewMonthModal v-if="newMonth" @close="newMonth = false"/>
  <AppModal v-if="lockConfirm" :title="w.plan.value?.locked ? 'Buka kunci bulan?' : 'Kunci jadwal bulan ini?'" @close="lockConfirm = false"><p class="text-sm leading-relaxed text-slate-500">{{ w.plan.value?.locked ? 'Penyusun dapat mengedit kembali tanggal yang terbuka.' : 'Setelah dikunci, isian bulan ini hanya dapat dibuka kembali oleh admin. Periksa catatan dinas sebelum menetapkan jadwal.' }}</p><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" @click="lockConfirm = false">Batal</button><button class="btn btn-primary" :disabled="w.saving.value" @click="toggleLock">{{ w.plan.value?.locked ? 'Buka kunci' : 'Kunci jadwal' }}</button></div></AppModal>
</template>
